@@ -1,50 +1,50 @@
 using sv_b0ac99e6421d49568ff113031e50c003.Client.Pages;
 using sv_b0ac99e6421d49568ff113031e50c003.Client.Services;
 using sv_b0ac99e6421d49568ff113031e50c003.Components;
 using sv_b0ac99e6421d49568ff113031e50c003.Services;

 var builder = WebApplication.CreateBuilder(args);

 // Add services to the container.
 builder.Services.AddRazorComponents()
     .AddInteractiveServerComponents()
     .AddInteractiveWebAssemblyComponents();

 builder.Services.AddScoped<IShipmentService, ShipmentService>();

 var app = builder.Build();

 // Configure the HTTP request pipeline.
 if (app.Environment.IsDevelopment())
 {
     app.UseWebAssemblyDebugging();
 }
 else
 {
     app.UseExceptionHandler("/Error", createScopeForErrors: true);
 }
 app.UseStatusCodePagesWithReExecute("/not-found", createScopeForStatusCodePages: true);
 app.UseAntiforgery();

 app.MapStaticAssets();

 app.MapGet("api/shipments/{trackingNumber}", async (string trackingNumber, IShipmentService service, CancellationToken ct) =>
 {
     try
     {
         var shipment = await service.GetShipmentAsync(trackingNumber, ct);
         return Results.Ok(shipment);
     }
     catch (KeyNotFoundException)
     {
         return Results.NotFound();
     }
 });

 app.MapRazorComponents<App>()
     .AddInteractiveServerRenderMode()
     .AddInteractiveWebAssemblyRenderMode()
     .AddAdditionalAssemblies(typeof(sv_b0ac99e6421d49568ff113031e50c003.Client._Imports).Assembly);

 app.Run();
